  vec4 texColor=texture2D(texture, v_uv0);
  float r=texColor.r;
  float g=texColor.g;
  float b=texColor.b;
  float a=texColor.a;
  float h;
  float s;
  float l;
  {
      float max=max(max(r,g),b);
      float min=min(min(r,g),b);
      if(max==min){
          h=0.0;
      }else if(max==r&&g>=b){
          h=60.0*(g-b)/(max-min)+0.0;
      }else if(max==r&&g<b){
          h=60.0*(g-b)/(max-min)+360.0;
      }else if(max==g){
          h=60.0*(b-r)/(max-min)+120.0;
      }else if(max==b){
          h=60.0*(r-g)/(max-min)+240.0;
      }
      l=0.5*(max+min);
