      if(l<0.5){
          q=l*(1.0+s);
      }else if(l>=0.5){
          q=l+s-l*s;
      }
      float p=2.0*l-q;
      float hk=h/360.0;
      float t[3];
      t[0]=hk+1.0/3.0;t[1]=hk;t[2]=hk-1.0/3.0;
