  float brightness;
      float saturation;
      float constrast;
      float gray;
      vec4  silhouette;
};
  vec3 lerp(vec3 a, vec3 b, float w){
      return a + w*(b-a);
  }
  vec4 updateColor(vec4 o)
{
      if(silhouette.r*silhouette.g*silhouette.b*silhouette.a!=1.0){
          o =vec4(silhouette.r, silhouette.g, silhouette.b, o.a*silhouette.a);
